    for b in data:
        freq[b] = freq.get(b, 0) + 1
    return sorted([(k, v) for k, v in freq.items()], key=lambda x: x[1], reverse=True)

def decrypt_xor_cycle(data, key):
    return bytes([a ^ b for a, b in zip(data, cycle(key))])

